import os
import zipfile
import asyncio
import logging


from jsilib.aio.api import read_all
from jsilib.aio.client import Client
from jsilib.aio.reactors import Reactor
from jsilib import helpers
from jsilib.jsi.connection import JSIConnection
from jsilib.jsi.messages import JSIBytesMessage
from jsilib.jsi.settings import Settings
from jsilib.jsonrpc.client import JSONRPCClient
from jsilib.transport.connection import TransportConnection


from taf.fdsw.rc.clients.websocket.jsilib.utils import (EventLoopThread,
                                                        NotificationHandler)
from taf.fdsw.rc.clients.exceptions import TimeoutExceeded


logger = logging.getLogger(__name__)
logger.addHandler(logging.NullHandler())


class Connection():

    def __init__(self):
        self.jsilib_client_thread = EventLoopThread()
        self.jsilib_client_thread.start()
        self.json_rpc_client = None
        self.notification_handler = NotificationHandler()
        self.closable_handlers = []

    def prepare_jsonrpc_client(self, ip_address, port):
        """
        Establish connection using jsilib client
        """
        try:
            self.json_rpc_client = self.jsilib_client_thread.run_coro(
                self._get_jsonrpc_client(ip_address, port)).result()

        except Exception as e:
            # ConnectFailedError > when RC is not reachable
            # InvalidStatusCode > when RC rejects connection
            # futures.TimeoutError > when smod is not pingable
            # TODO ConnectionRefusedError > investigate root couse and add to handled exceptions
            # TODO remove this brutal solution once what above is done
            self.disconnect()
            raise e

    def send(self, method, parameters=None, payload=None, sid=None):
        if payload:
            payload = JSIBytesMessage(payload)
        return self.jsilib_client_thread.run_coro(
            self.json_rpc_client.execute(method=method, params=parameters, body=payload, sid=sid)).result()

    def _set_subscriber(self, method):
        """
        Subscribe to chosen method using jsilib subscriber
        """
        self.json_rpc_client.subscribe(subscriber=self.notification_handler.set_subscriber, method=method)

    async def _get_jsonrpc_client(self, ip_address, port):
        """
        JSONRPCClient requires all connection layers to be initialized
        their handlers are stored in closable_handlers var to be used on close
        """
        api_url = 'wss://{}:{}/ws/?no_cert_validation=1'.format(ip_address, port)
        reactor = Reactor()
        client = Client(reactor)
        self.closable_handlers.extend([reactor, client])  # add to closable_handlers in case client.connect() fails
        # removed Exceptions from args for default behaviour / expose timeout to interface level in future release
        stream = await helpers.repeat_until_returns(lambda: client.connect(api_url), timeout=10)

        transport_connection = TransportConnection(reactor, stream)
        settings = Settings()
        settings.chunk_size = 2 ** 23 - 1  # so far reading Chunk messages on SWIM side is bugged, large message size is needed to avoid chunking
        jsi_connection = JSIConnection(reactor, transport_connection, settings=settings)
        jsonrpc_client = JSONRPCClient(reactor, jsi_connection)
        self.closable_handlers.extend([stream, transport_connection, jsi_connection, jsonrpc_client])
        return jsonrpc_client

    def get_diagnostics(self, endpoint, path, sid, timeout):

        async def request_logs(sid):
            return await self.json_rpc_client.execute(
                method=endpoint,
                sid=sid)

        async def get_file(sid, path):
            resp = await request_logs(sid)

            content = resp.body
            content_read = b''
            content_read += await read_all(content, content.bytes_left())
            file_path = os.path.join(path, resp.head.result)
            with open(file_path, "w") as f:
                f.write(content_read.decode())
            return file_path
        return self.jsilib_client_thread.run_coro(get_file(sid, path)).result()

    def get_files(self, zip_path, sid, timeout):
        async def request_logs(sid):
            return await self.json_rpc_client.execute(
                method='diagnostics.logs.downloadFile',  # TODO request definition should be in diagnostic interface
                sid=sid)

        async def get_files(sid, zip_obj):
            while True:
                resp = await request_logs(sid)
                if resp.head.result is None:
                    break
                await self._file_reciever(resp, zip_obj)

        try:
            with zipfile.ZipFile(zip_path, mode='w', compression=zipfile.ZIP_DEFLATED) as zip_obj:
                coro = asyncio.wait_for(get_files(sid, zip_obj), timeout)
                self.jsilib_client_thread.run_coro(coro).result()
        except asyncio.TimeoutError as e:
            logger.error(e, exc_info=True)
            raise TimeoutExceeded

    async def _file_reciever(self, resp, zip_obj):
        read_chunk_size = 256 * 102
        file_name = os.path.basename(resp.head.result)
        content = resp.body
        content_read = b''
        while content.bytes_left() > 0:
            chunk = await read_all(content, min(read_chunk_size, content.bytes_left()))
            content_read += chunk
        zip_obj.writestr(file_name, content_read)

    def disconnect(self):
        """
        Ensure all connection layers are properly closed using closing method from jsilib
        """
        async def close_jsilib():
            async with helpers.closing(*self.closable_handlers):
                pass
        self.jsilib_client_thread.run_coro(close_jsilib()).result()
        self.jsilib_client_thread.stop()
